DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `recalculate_allocated_stock` (IN `p_item_id` INT)   BEGIN
    DECLARE v_stock      INT DEFAULT 0;
    DECLARE v_assigned   INT DEFAULT 0;
    DECLARE v_sisa       INT DEFAULT 0;
    DECLARE v_rank       INT DEFAULT 0;
    DECLARE v_winner_id  INT DEFAULT NULL;

    -- 1. Ambil current_stock
    SELECT current_stock INTO v_stock
    FROM items WHERE id = p_item_id;

    -- 2. Set semua = FLOOR(stock * pct / 100)
    UPDATE model_items
    SET allocated_stock = FLOOR(v_stock * allocation_percentage / 100)
    WHERE item_id = p_item_id;

    -- 3. Hitung total sudah dialokasikan & sisa
    SELECT COALESCE(SUM(allocated_stock), 0) INTO v_assigned
    FROM model_items WHERE item_id = p_item_id;

    SET v_sisa = v_stock - v_assigned;

    -- 4. Bagi sisa 1 per 1 ke model dengan remainder terbesar
    --    Gunakan loop: setiap iterasi ambil 1 model teratas berdasarkan remainder
    --    lalu tambah allocated_stock-nya +1, dan kurangi sisa
    WHILE v_sisa > 0 DO

        -- Ambil id model dengan remainder terbesar pada urutan ke-N dari atas
        -- N = sudah berapa kali loop berjalan (ditandai dari v_stock - v_sisa - v_assigned + 1)
        -- Trick: pakai LIMIT 1 OFFSET (loop_count)
        SET v_rank = v_stock - v_assigned - v_sisa;

        SELECT id INTO v_winner_id
        FROM model_items
        WHERE item_id = p_item_id
          AND allocation_percentage > 0
        ORDER BY
            (v_stock * allocation_percentage / 100)
            - FLOOR(v_stock * allocation_percentage / 100) DESC,
            id ASC
        LIMIT 1 OFFSET v_rank;

        IF v_winner_id IS NOT NULL THEN
            UPDATE model_items
            SET allocated_stock = allocated_stock + 1
            WHERE id = v_winner_id;
        END IF;

        SET v_sisa = v_sisa - 1;
    END WHILE;

END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `recalculate_all_allocated_stock` ()   BEGIN
    DECLARE v_done    INT DEFAULT FALSE;
    DECLARE v_item_id INT;

    DECLARE cur CURSOR FOR
        SELECT DISTINCT item_id FROM model_items;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = TRUE;

    OPEN cur;
    read_loop: LOOP
        FETCH cur INTO v_item_id;
        IF v_done THEN LEAVE read_loop; END IF;
        CALL recalculate_allocated_stock(v_item_id);
    END LOOP;
    CLOSE cur;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `recalculate_safety_stock` (IN `p_item_id` INT)   BEGIN
    DECLARE v_location_id INT;
    DECLARE v_working_days_month INT;
   
    SELECT location_id INTO v_location_id
    FROM items WHERE id = p_item_id LIMIT 1;
   
    SELECT working_days_per_month INTO v_working_days_month
    FROM location_settings WHERE location_id = v_location_id LIMIT 1;
   
    IF v_working_days_month IS NULL OR v_working_days_month = 0 THEN
        SET v_working_days_month = 22;
    END IF;
   
    UPDATE model_items
    SET safety_stock = CEILING(
        (monthly_plan / v_working_days_month) * working_days_per_week
    )
    WHERE item_id = p_item_id
      AND monthly_plan > 0
      AND working_days_per_week > 0;
     
    UPDATE model_items
    SET safety_stock = 0
    WHERE item_id = p_item_id
      AND (monthly_plan = 0 OR working_days_per_week = 0);
END$$

DELIMITER ;

