DELIMITER $$
CREATE TRIGGER `trg_items_stock_update` AFTER UPDATE ON `items` FOR EACH ROW BEGIN
  IF NEW.current_stock <> OLD.current_stock THEN
    CALL recalculate_allocated_stock(NEW.id);
  END IF;
END
$$
