--
-- Table structure for table `model_items`
--

CREATE TABLE `model_items` (
  `id` int(11) NOT NULL,
  `model_id` int(11) NOT NULL,
  `item_id` int(11) NOT NULL,
  `usage_qty` int(11) NOT NULL DEFAULT 1,
  `allocation_percentage` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT 'Persentase alokasi stock dari total current_stock item (0-100%)',
  `safety_stock` int(11) NOT NULL DEFAULT 0,
  `working_days_per_week` int(11) DEFAULT 5,
  `monthly_plan` int(11) NOT NULL DEFAULT 0 COMMENT 'Rencana produksi bulanan per model, digunakan sebagai dasar perhitungan allocation_percentage',
  `allocated_stock` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'Jumlah stock yang dialokasikan ke model ini',
  `production_status` tinyint(1) DEFAULT 0 COMMENT '0=STOP, 1=RUN'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

