--
-- Triggers `model_items`
--
DELIMITER $$
CREATE TRIGGER `before_model_items_update_safety` BEFORE UPDATE ON `model_items` FOR EACH ROW BEGIN
    DECLARE v_location_id INT;
    DECLARE v_working_days_month INT;
   
    IF NEW.monthly_plan != OLD.monthly_plan 
       OR NEW.working_days_per_week != OLD.working_days_per_week THEN
       
        SELECT location_id INTO v_location_id
        FROM items WHERE id = NEW.item_id LIMIT 1;
       
        SELECT working_days_per_month INTO v_working_days_month
        FROM location_settings WHERE location_id = v_location_id LIMIT 1;
       
        IF v_working_days_month IS NULL OR v_working_days_month = 0 THEN
            SET v_working_days_month = 22;
        END IF;
       
        IF NEW.monthly_plan > 0 AND NEW.working_days_per_week > 0 THEN
            SET NEW.safety_stock = CEILING(
                (NEW.monthly_plan / v_working_days_month) * NEW.working_days_per_week
            );
        ELSE
            SET NEW.safety_stock = 0;
        END IF;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_model_items_insert` BEFORE INSERT ON `model_items` FOR EACH ROW BEGIN
  DECLARE v_total_persen DECIMAL(7,2) DEFAULT 0.00;

  IF @disable_alloc_check IS NULL OR @disable_alloc_check = 0 THEN

    SELECT COALESCE(SUM(allocation_percentage), 0) INTO v_total_persen
    FROM `model_items`
    WHERE item_id = NEW.item_id;

    IF (v_total_persen + NEW.allocation_percentage) > 100 THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Gagal: Total allocation_percentage untuk item ini melebihi 100%';
    END IF;

  END IF;

END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_model_items_update` BEFORE UPDATE ON `model_items` FOR EACH ROW BEGIN
  DECLARE v_total_persen DECIMAL(7,2) DEFAULT 0.00;

  -- Jika flag bypass aktif (misal dari calculate_from_safety.php), skip validasi
  IF @disable_alloc_check IS NULL OR @disable_alloc_check = 0 THEN

    -- Cek total % dari model LAIN (exclude row yang sedang di-update)
    SELECT COALESCE(SUM(allocation_percentage), 0) INTO v_total_persen
    FROM `model_items`
    WHERE item_id = NEW.item_id
      AND id <> NEW.id;

    -- Tolak jika total (tanpa row ini) + nilai baru melebihi 100%
    IF (v_total_persen + NEW.allocation_percentage) > 100 THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Gagal: Total allocation_percentage untuk item ini melebihi 100%';
    END IF;

  END IF;

END
$$
DELIMITER ;

